import React, { useEffect,useState } from 'react'
import axios from 'axios';
import { useParams } from 'react-router';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

function DisplayItem() {
    const [inventory , setInventory] = useState([]);
    const {id} = useParams();
    
    useEffect(() => {
        loadInventory();
    }, [])

    const loadInventory = async () => {
        const result = await axios.get("http://localhost:8080/inventory")
        setInventory(result.data);
    }

    const UpdateNavigate = (id) => {
        window.location.href=`/updateitem/${id}`;
    }

    const deleteItem = async (id) => {
        const confirmationMessage = window.confirm("Are you sure you want to delete this item?")
        if (confirmationMessage) {
            try {
                await axios.delete(`http://localhost:8080/inventory/${id}`);
                loadInventory(); // Reload the inventory after deletion
                alert("Item deleted successfully");
            }
            catch (error) {
                alert("Failed to delete item");
            }
        }
    }

    const generatePDF = (inventory) => {
        const doc = new jsPDF("portrait"); // Change 1: Proper Constructor

        doc.setFontSize(18);
        doc.text("Inventory Items", 14, 15); // Change 2: Adjusted Y-axis

        const tableData = inventory.map(item => [
            item.itemId,
            item.itemName,
            item.itemCategory,
            item.itemQty,
            item.itemDetails
        ]);

        // Change: Use autoTable as a function, not a method
        autoTable(doc, {
            head: [['Item ID', 'Item Name', 'Category', 'Quantity', 'Details']],
            body: tableData,
            startY: 25,
            theme: 'striped',
            headStyles: { fillColor: [41, 128, 185] } 
        });

        doc.save("inventory_items.pdf");
    }

    //search function
    const [searchQuery, setSearchQuery] = useState("");



  return (
    <div>
      <h1>Inventory Item</h1>
      <button onClick={() => generatePDF(inventory)}>Generate PDF</button>
      <table>
        <thead>
          <tr>
            <th>Item ID</th>
            <th>Item</th>
            <th>Item Name</th>
            <th>Category</th>
            <th>Quantity</th>
            <th>Details</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
            {inventory.map((item, index) => (
                <tr key={index}>
                    <td>{item.itemId}</td>
                    <td>
                        <img src ={`http://localhost:8080/uploads/${item.itemImage}`} 
                        alt={item.itemName} 
                        width="50" height="50"/>
                    </td>
                    <td>{item.itemName}</td>
                    <td>{item.itemCategory}</td>
                    <td>{item.itemQty}</td>
                    <td>{item.itemDetails}</td>
                    <td>
                        <button onClick={() => UpdateNavigate(item.id)}>Update</button>
                        <button onClick={() => deleteItem(item.id)}>Delete</button>
                    </td>
                </tr>
            ))}
        </tbody>
      </table>
    </div>
  )
}

export default DisplayItem
